def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # The isolated 7 is a directional marker; recolor the first object
    # directly below it to the marker's color.
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 7]
    for r, c in markers:
        # Ignore 7s belonging to multi-cell components.
        if sum(0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 7
               for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))) > 0:
            continue
        rr = r + 1
        while rr < h and grid[rr][c] == bg:
            rr += 1
        if rr < h:
            target = grid[rr][c]
            if target != bg and target != 7:
                todo = [(rr, c)]
                cells = {(rr, c)}
                while todo:
                    x, y = todo.pop()
                    for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                        if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == target and (nx,ny) not in cells:
                            cells.add((nx,ny)); todo.append((nx,ny))
                for x, y in cells:
                    out[x][y] = 7
                return out
    return out

