from collections import Counter, deque


def _orientations(points):
    result = set()
    for flip in (1, -1):
        for rot in range(4):
            shape = []
            for y, x in points:
                x *= flip
                for _ in range(rot):
                    y, x = x, -y
                shape.append((y, x))
            my = min(y for y, x in shape)
            mx = min(x for y, x in shape)
            result.add(frozenset((y-my, x-mx) for y, x in shape))
    return result


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            seen.add((r, c))
            queue = deque([(r, c)])
            cells = set()
            while queue:
                y, x = queue.popleft()
                cells.add((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if (0 <= yy < h and 0 <= xx < w and
                        (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        queue.append((yy, xx))
            comps.append((color, cells))
    return comps


def _embeds(small, large):
    for shape in _orientations(small):
        for ay, ax in large:
            if {(ay+y, ax+x) for y, x in shape} <= large:
                return True
    return False


def transform(grid):
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    comps = _components(grid, background)
    options = []
    for i, (color, cells) in enumerate(comps):
        for j, (host_color, host) in enumerate(comps):
            if i != j and color != host_color and len(host) > len(cells) and _embeds(cells, host):
                options.append((min(r for r,c in cells), min(c for r,c in cells), i, host_color))
                break
    out = [row[:] for row in grid]
    if options:
        _, _, i, new_color = min(options)
        for r, c in comps[i][1]:
            out[r][c] = new_color
    return out


