def transform(grid):
    """Recolor the longest interior color-2 vertical component as color 3."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            seen.add((r, c))
            q = deque([(r, c)])
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if (0 <= yy < h and 0 <= xx < w and
                        (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append((color, cells))
    eligible = []
    for color, cells in comps:
        cols = {c for r, c in cells}
        rows = {r for r, c in cells}
        if color == 2 and len(cols) == 1 and len(rows) == len(cells) and len(cells) >= 3:
            eligible.append(cells)
    out = [row[:] for row in grid]
    if eligible:
        chosen = max(eligible, key=len)
        for r, c in chosen:
            out[r][c] = 3
    return out

