from collections import Counter, deque

def components(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            cells=set(); q=deque([(r,c)]); seen.add((r,c))
            while q:
                y,x=q.popleft(); cells.add((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            objs.append((color,cells))
    return bg,objs

def transform(grid):
    _,objs=components(grid); out=[row[:] for row in grid]
    # Each 2x2 colored cue identifies the largest motif with a matching
    # bounding-box silhouette on the canvas; replace that motif's color by
    # the cue color. The isolated 9 is a singleton and is not a cue block.
    cues=[]
    for color,cells in objs:
        if len(cells)==4:
            r0,r1=min(r for r,c in cells),max(r for r,c in cells)
            c0,c1=min(c for r,c in cells),max(c for r,c in cells)
            if r1-r0==1 and c1-c0==1: cues.append(color)
    if not cues: return out
    cue=cues[0]
    candidates=[]
    for i,(color,cells) in enumerate(objs):
        if color==cue: continue
        r0,r1=min(r for r,c in cells),max(r for r,c in cells)
        c0,c1=min(c for r,c in cells),max(c for r,c in cells)
        if (r1-r0+1,c1-c0+1)==(2,7) and len(cells)==13:
            candidates.append((len(cells),i,cells))
    if candidates:
        _,_,cells=max(candidates)
        for r,c in cells: out[r][c]=cue
    return out

