from collections import Counter, deque

def components(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            cells=set(); q=deque([(r,c)]); seen.add((r,c))
            while q:
                y,x=q.popleft(); cells.add((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            objs.append((color,cells))
    return bg,objs

def transform(grid):
    _,objs=components(grid); out=[row[:] for row in grid]
    # Find repeated silhouettes with different colors and recolor the more
    # compact top-left member to the color of its lower/right counterpart.
    def signature(cells):
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        return frozenset((r-r0,c-c0) for r,c in cells)
    groups={}
    for color,cells in objs:
        groups.setdefault(signature(cells),[]).append((color,cells))
    for group in groups.values():
        if len(group)<2 or len({c for c,_ in group})<2: continue
        # Choose the identical motif at the smallest row/column as target and
        # use the color of the next occurrence in scan order.
        group.sort(key=lambda obj:(min(r for r,c in obj[1]),min(c for r,c in obj[1])))
        (old,cells),(new,_) = group[0],group[-1]
        for r,c in cells: out[r][c]=new
        return out
    return out

