def components(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            cells=set(); q=deque([(r,c)]); seen.add((r,c))
            while q:
                y,x=q.popleft(); cells.add((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            objs.append((color,cells))
    return bg,objs

def transform(grid):
    _,objs=components(grid); out=[row[:] for row in grid]
    # Compare motif components by exact silhouette. A matching motif rendered
    # in a different color is the intended color correction; normalize by
    # translation and choose the motif whose counterpart is closest in size.
    def sig(cells):
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        return frozenset((r-r0,c-c0) for r,c in cells)
    shapes={}
    for color,cells in objs:
        shapes.setdefault(sig(cells),[]).append((color,cells))
    for variants in shapes.values():
        colors={c for c,_ in variants}
        if len(variants)>1 and len(colors)>1:
            # Prefer changing the larger of a repeated silhouette pair.
            variants.sort(key=lambda x:len(x[1]))
            small_color,small_cells=variants[0]
            target_color=variants[-1][0]
            for r,c in small_cells: out[r][c]=target_color
            return out
    return out

