def _normalize(points):
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    return frozenset((r-r0, c-c0) for r, c in points)


def _orientations(points):
    forms = set()
    for flip in (1, -1):
        for turns in range(4):
            transformed = []
            for r, c in points:
                x, y = r, c * flip
                for _ in range(turns):
                    x, y = y, -x
                transformed.append((x, y))
            forms.add(_normalize(transformed))
    return forms


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            seen.add((r, c))
            stack = [(r, c)]
            points = []
            while stack:
                x, y = stack.pop()
                points.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        stack.append((nx,ny))
            components.append((color, points))

    # The large bent line is the palette key; its color is the replacement color.
    marker = None
    for color, points in components:
        rs = [r for r,c in points]
        cs = [c for r,c in points]
        bh, bw = max(rs)-min(rs)+1, max(cs)-min(cs)+1
        if len(points) >= 8 and bh >= 4 and bw >= 4 and bh*bw > len(points)*2:
            if marker is None or len(points) > len(marker[1]):
                marker = (color, points)
    if marker is None:
        return [row[:] for row in grid]
    key_color = marker[0]

    # Identify duplicated object silhouettes; recolor the uppermost member to the key color.
    matches = []
    for i, (color, points) in enumerate(components):
        shape = _orientations(points)
        for j, (other_color, other_points) in enumerate(components):
            if i == j or color == other_color or len(points) != len(other_points):
                continue
            if shape & _orientations(other_points):
                matches.append((min(r for r,c in points), min(c for r,c in points), points))
                break
    if not matches:
        return [row[:] for row in grid]
    _, _, target = min(matches, key=lambda item: (item[0], item[1]))
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = key_color
    return out


