from collections import Counter


def transform(grid):
    """Restore erased cells in a framed diagonal-periodic color field."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    samples = [(r, c, grid[r][c])
               for r in range(3, h) for c in range(3, w)
               if grid[r][c] != 0]

    # Find the shortest diagonal period that explains the interior samples.
    period = None
    mapping = None
    for p in range(2, min(10, h + w) + 1):
        counts = [Counter() for _ in range(p)]
        for r, c, color in samples:
            counts[(r + c) % p][color] += 1
        winners = [count.most_common(1)[0][0] if count else None
                   for count in counts]
        total = sum(sum(count.values()) for count in counts)
        correct = sum(max(count.values()) for count in counts if count)
        if total and correct / total >= 0.88 and all(winners):
            period, mapping = p, winners
            break
    if mapping is None:
        raise ValueError("Could not infer the interior diagonal color cycle")

    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = mapping[(r + c) % period]
    return out


