from collections import Counter
from itertools import combinations


def _regular_sequences(indices):
    vals = sorted(set(indices))
    seqs = set()
    for a, b in combinations(vals, 2):
        step = b - a
        seq = []
        x = a
        while x in vals:
            seq.append(x)
            x += step
        if len(seq) >= 2:
            seqs.add(tuple(seq))
    return sorted(seqs, key=lambda s: (len(s), - (s[1] - s[0])), reverse=True)


def transform(grid):
    h, w = len(grid), len(grid[0])
    all_colors = set(v for row in grid for v in row)
    best = None

    # Find the repeated row/column lattice. The rail color nearly fills each
    # separator, while ordinary cells in the panel interiors share a base color.
    for rail in all_colors:
        row_candidates = [r for r in range(h) if sum(v == rail for v in grid[r]) >= 0.8 * w]
        col_candidates = [c for c in range(w) if sum(grid[r][c] == rail for r in range(h)) >= 0.8 * h]
        for rows in _regular_sequences(row_candidates):
            for cols in _regular_sequences(col_candidates):
                interior = [grid[r][c] for r in range(h) for c in range(w)
                            if r not in rows and c not in cols and grid[r][c] != rail]
                if not interior:
                    continue
                base = Counter(interior).most_common(1)[0][0]
                matrix = [[grid[r][c] for c in cols] for r in rows]
                markers = [(r, c) for r, row in enumerate(matrix)
                           for c, value in enumerate(row)
                           if value != rail and value != base]
                if not markers:
                    continue
                # Highest marker count and lattice coverage favor the intended rails.
                rank = (len(markers), len(rows) * len(cols), len(rows) + len(cols))
                if best is None or rank > best[0]:
                    best = (rank, matrix, base, rail)

    if best is None:
        raise ValueError('No repeated marker lattice found')
    _, matrix, base, rail = best

    # Rail-color crossings are ordinary blank cells in the compact pattern;
    # exceptional crossing colors are copied as markers.
    out = [[base if value == rail else value for value in row] for row in matrix]
    marked = [(r, c) for r, row in enumerate(out) for c, value in enumerate(row) if value != base]
    r0, r1 = min(r for r, _ in marked), max(r for r, _ in marked)
    c0, c1 = min(c for _, c in marked), max(c for _, c in marked)
    return [row[c0:c1 + 1] for row in out[r0:r1 + 1]]


