                if b-a==d-c: cand.append((b-a,'v',color,a,b,c,d))
    if not cand: return [row[:] for row in grid]
    _,axis,frame,a,b,c,d=max(cand)
    other=[v for v in cnt if v not in (bg,frame)]
    if not other: return [row[:] for row in grid]
    clue=min(other,key=lambda v:cnt[v])
    fill=clue
    out=[row[:] for row in grid]
    if axis=='h':
        # Boundary bars launch parallel rays spanning the gap, with clues
        # acting as stopping points and changing to the highlight color.
        for col in range(a,b):
            for r in range(1,h-1):
                v=grid[r][col]
                if v==clue: out[r][col]=4; break
                if v==bg: out[r][col]=fill
        for col in range(c,d):
            for r in range(h-2,0,-1):
                v=grid[r][col]
                if v==clue: out[r][col]=4; break
                if v==bg: out[r][col]=fill
        # The upper and lower border marks extend their fill toward the
        # corresponding opposite bar over the unmatched offset columns.
        for col in range(b,w):
            if grid[0][col]==bg: out[0][col]=fill
        for col in range(0,c):
            if grid[-1][col]==bg: out[-1][col]=fill
    else:
        for r in range(a,b):
            for col in range(1,w-1):
                v=grid[r][col]
                if v==clue: out[r][col]=4; break
                if v==bg: out[r][col]=fill
        for r in range(c,d):
            for col in range(w-2,0,-1):
                v=grid[r][col]
                if v==clue: out[r][col]=4; break
                if v==bg: out[r][col]=fill
        for r in range(b,h):
