def _runs(seq, color):
    runs, start = [], None
    for i, value in enumerate(seq + [None]):
        if value == color and start is None:
            start = i
        elif value != color and start is not None:
            runs.append((start, i))
            start = None
    return runs


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    matches = []
    for color in counts:
        if color == background:
            continue
        for a, b in _runs(grid[0], color):
            for c, d in _runs(grid[-1], color):
                if b - a == d - c:
                    matches.append((b-a, 'horizontal', color, a, b, c, d))
        left = [grid[r][0] for r in range(h)]
        right = [grid[r][-1] for r in range(h)]
        for a, b in _runs(left, color):
            for c, d in _runs(right, color):
                if b - a == d - c:
                    matches.append((b-a, 'vertical', color, a, b, c, d))
    if not matches:
        return [row[:] for row in grid]
    _, axis, frame, a, b, c, d = max(matches)
    extras = [v for v in counts if v not in (background, frame)]
    if not extras:
        return [row[:] for row in grid]
    clue = min(extras, key=lambda v: counts[v])
    fill = clue
    out = [row[:] for row in grid]
    if axis == 'horizontal':
        # Fill the complete quadrilateral band between the opposing bars;
        # original clue points are shown as 4, while the bars are preserved.
        left, right = min(a, c), max(b, d)
        for r in range(1, h-1):
            for col in range(left, right):
                value = grid[r][col]
                if value == background:
                    out[r][col] = fill
                elif value == clue:
                    out[r][col] = 4
        # Border extensions use the differences in bar offsets, as in the
        # demonstrations' upper-right and lower-left continuations.
        for col in range(b, w):
            if grid[0][col] == background:
                out[0][col] = fill
        for col in range(c):
            if grid[-1][col] == background:
                out[-1][col] = fill
    else:
        top, bottom = min(a, c), max(b, d)
        for r in range(top, bottom):
            for col in range(1, w-1):
                value = grid[r][col]
                if value == background:
                    out[r][col] = fill
                elif value == clue:
                    out[r][col] = 4
        for r in range(b, h):
            if grid[r][0] == background:
                out[r][0] = fill
        for r in range(c):
            if grid[r][-1] == background:
                out[r][-1] = fill
    return out

