def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Find equal-length, same-color runs on opposite borders. Each cell of a
    # run casts a ray inward; sparse non-background clues stop the ray and
    # become endpoint color 4.
    candidates = []
    for color in counts:
        if color == background:
            continue
        top_runs = _runs(grid[0], color)
        bottom_runs = _runs(grid[-1], color)
        for a, b in top_runs:
            for c, d in bottom_runs:
                if b - a == d - c:
                    candidates.append((b-a, 'horizontal', color, a, b, c, d))
        left = [grid[r][0] for r in range(h)]
        right = [grid[r][-1] for r in range(h)]
        for a, b in _runs(left, color):
            for c, d in _runs(right, color):
                if b - a == d - c:
                    candidates.append((b-a, 'vertical', color, a, b, c, d))
    if not candidates:
        return [row[:] for row in grid]
    _, axis, frame, a, b, c, d = max(candidates)
    clues = [value for value in counts if value not in (background, frame)]
    if not clues:
        return [row[:] for row in grid]
    fill = min(clues, key=lambda value: counts[value])
    out = [row[:] for row in grid]

    def ray(row, col, dr, dc):
        r, x = row + dr, col + dc
        while 0 <= r < h and 0 <= x < w:
            value = grid[r][x]
            if value == background:
                out[r][x] = fill
            elif value != frame:
                out[r][x] = 4
                break
            r += dr
            x += dc

    if axis == 'horizontal':
        for col in range(a, b):
            ray(0, col, 1, 0)
        for col in range(c, d):
            ray(h-1, col, -1, 0)
    else:
        for row in range(a, b):
            ray(row, 0, 0, 1)
        for row in range(c, d):
            ray(row, w-1, 0, -1)
    return out


