        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Border runs are launch bars. Their perpendicular rays paint the
    # background with the interior clue color, changing each first clue hit
    # to 4 and stopping there.
    edge_counts = {}
    for c in range(w):
        for r in (0, h - 1):
            value = grid[r][c]
            if value != background:
                edge_counts[value] = edge_counts.get(value, 0) + 1
    for r in range(h):
        for c in (0, w - 1):
            value = grid[r][c]
            if value != background:
                edge_counts[value] = edge_counts.get(value, 0) + 1
    if not edge_counts:
        return out
    bar_color = max(edge_counts, key=edge_counts.get)
    marker_colors = [v for v in counts if v not in (background, bar_color)]
    if not marker_colors:
        return out
    fill_color = min(marker_colors, key=lambda v: counts[v])

    def ray(r, c, dr, dc):
        r += dr
        c += dc
        while 0 <= r < h and 0 <= c < w:
            value = grid[r][c]
            if value == background:
                out[r][c] = fill_color
            elif value != bar_color:
                out[r][c] = 4
                break
            r += dr
            c += dc

    # Cast inward from every cell of the dominant non-background border bar.
    for c in range(w):
        if grid[0][c] == bar_color:
            ray(0, c, 1, 0)
        if grid[h - 1][c] == bar_color:
            ray(h - 1, c, -1, 0)
    for r in range(h):
        if grid[r][0] == bar_color:
            ray(r, 0, 0, 1)
        if grid[r][w - 1] == bar_color:
            ray(r, w - 1, 0, -1)
    return out


