def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # The edge runs act as short bars in two matching border fields. Resolve
    # each clue by its row/column alignment with a bar and extend to the
    # appropriate edge, using the interior color as the ray color.
    edge_counts = Counter()
    for r in range(h):
        for c in range(w):
            if r in (0, h - 1) or c in (0, w - 1):
                if grid[r][c] != background:
                    edge_counts[grid[r][c]] += 1
    if not edge_counts:
        return out
    bar = edge_counts.most_common(1)[0][0]
    other = [v for v in counts if v not in (background, bar)]
    if not other:
        return out
    clue = min(other, key=counts.get)

    # Gather contiguous reference bars along all four sides.
    def runs(seq, color):
        found, start = [], None
        for i, value in enumerate(seq + [None]):
            if value == color and start is None:
                start = i
            elif value != color and start is not None:
                found.append((start, i))
                start = None
        return found

    top, bottom = runs(grid[0], bar), runs(grid[-1], bar)
    left, right = runs([grid[r][0] for r in range(h)], bar), runs([grid[r][-1] for r in range(h)], bar)

    # For each clue that lies in the projection of any boundary segment,
    # paint its row/column to the matching bar. The clue is highlighted 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != clue:
                continue
            directions = []
            if any(a <= c < b for a, b in top):
                directions.append((-1, 0))
            if any(a <= c < b for a, b in bottom):
                directions.append((1, 0))
            if any(a <= r < b for a, b in left):
                directions.append((0, -1))
            if any(a <= r < b for a, b in right):
                directions.append((0, 1))
            if not directions:
                continue
            out[r][c] = 4
            for dr, dc in directions:
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] != background:
                        break
                    out[rr][cc] = clue
                    rr += dr
                    cc += dc
    return out


