        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Find the repeated color used for opposing edge bars, and the sparse
    # interior color that marks the region to be drawn.
    edge_counts = {}
    for r in range(h):
        for c in range(w):
            if r in (0, h - 1) or c in (0, w - 1):
                value = grid[r][c]
                if value != background:
                    edge_counts[value] = edge_counts.get(value, 0) + 1
    if not edge_counts:
        return [row[:] for row in grid]
    bar = max(edge_counts, key=edge_counts.get)
    sparse = [value for value in counts if value not in (background, bar)]
    if not sparse:
        return [row[:] for row in grid]
    marker = min(sparse, key=lambda value: counts[value])
    out = [row[:] for row in grid]

    def runs(line):
        result, start = [], None
        for i, value in enumerate(line + [None]):
            if value == bar and start is None:
                start = i
            elif value != bar and start is not None:
                result.append((start, i))
                start = None
        return result

    # Equal-length bars on opposite borders delimit a common projected span.
    edge_pairs = []
    for first, second in ((grid[0], grid[-1]),
                          ([grid[r][0] for r in range(h)],
                           [grid[r][-1] for r in range(h)])):
        for a in runs(first):
            for b in runs(second):
                if a[1] - a[0] == b[1] - b[0]:
                    edge_pairs.append((a, b))

    if edge_pairs:
        # Fill the combined coordinate interval between the paired bars.
        # Preserve original bars and recolor sparse marker cells to 4.
        for a, b in edge_pairs:
            lo, hi = min(a[0], b[0]), max(a[1], b[1])
            if a is runs(grid[0]):
                pass
            # Determine orientation from the actual border runs.
            vertical_pair = any(
                grid[0][i] == bar for i in range(a[0], a[1])
            ) or any(grid[-1][i] == bar for i in range(b[0], b[1]))
            if vertical_pair:
                for r in range(1, h - 1):
                    for c in range(lo, min(hi, w)):
                        if grid[r][c] == background or grid[r][c] == marker:
                            out[r][c] = marker
            else:
                for r in range(lo, min(hi, h)):
                    for c in range(1, w - 1):
                        if grid[r][c] == background or grid[r][c] == marker:
                            out[r][c] = marker

    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                out[r][c] = 4
    return out


