        runs = []
        i = 0
        while i < len(line):
            if line[i] == background:
                i += 1
                continue
            color = line[i]
            j = i + 1
            while j < len(line) and line[j] == color:
                j += 1
            runs.append((i, j, color))
            i = j
        return runs

