    if h > 1:
        top = edge_runs(grid[0])
        bottom = edge_runs(grid[-1])
        for run in top:
            if any(run[1] - run[0] == b[1] - b[0] and run[2] == b[2] for b in bottom):
                bars.append(('top', run))
        for run in bottom:
            if any(run[1] - run[0] == a[1] - a[0] and run[2] == a[2] for a in top):
                bars.append(('bottom', run))

    # Or matching left/right edge bars create horizontal lanes.
    if not bars and w > 1:
        left = edge_runs([grid[r][0] for r in range(h)])
        right = edge_runs([grid[r][-1] for r in range(h)])
        for run in left:
            if any(run[1] - run[0] == b[1] - b[0] and run[2] == b[2] for b in right):
                bars.append(('left', run))
        for run in right:
            if any(run[1] - run[0] == a[1] - a[0] and run[2] == a[2] for a in left):
                bars.append(('right', run))

