def transform(grid):
    """Overlay four same-sized panels, with precedence panel 2, 3, 0, 1."""
    h = len(grid)
    if not h:
        return []
    w = len(grid[0])
    dividers = [c for c in range(w) if all(row[c] == 3 for row in grid)]
    if len(dividers) != 3:
        raise ValueError("expected three full-height divider columns")
    bounds = [-1] + dividers + [w]
    panels = []
    for i in range(4):
        lo, hi = bounds[i] + 1, bounds[i + 1]
        panel = [row[lo:hi] for row in grid]
        panels.append(panel)
    widths = {len(row) for panel in panels for row in panel}
    if len(widths) != 1:
        raise ValueError("panels must have equal widths")
    out = [[0] * len(panels[0][0]) for _ in range(h)]
    for p in (1, 0, 3, 2):
        for r in range(h):
            for c, value in enumerate(panels[p][r]):
                if value != 0:
                    out[r][c] = value
    return out

