from collections import Counter


def transform(grid):
    """Stamp the embedded horizontal motif at each isolated marker, centered on it."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The motif is the longest contiguous run of non-background cells in any row.
    candidates = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == background:
                c += 1
                continue
            start = c
            while c < w and row[c] != background:
                c += 1
            if c - start > 1:
                candidates.append((c - start, r, start, list(row[start:c])))
    if not candidates:
        return [list(row) for row in grid]
    _, motif_row, motif_start, motif = max(candidates)

    # Isolated non-background cells outside that motif row are placement anchors.
    counts = Counter(
        grid[r][c]
        for r in range(h) if r != motif_row
        for c in range(w) if grid[r][c] != background
    )
    if not counts:
        return [list(row) for row in grid]
    marker = counts.most_common(1)[0][0]

    out = [list(row) for row in grid]
    anchor_offset = len(motif) // 2
    for r in range(h):
        if r == motif_row:
            continue
        for c in range(w):
            if grid[r][c] == marker:
                left = c - anchor_offset
                for j, color in enumerate(motif):
                    target = left + j
                    if 0 <= target < w:
                        out[r][target] = color
