from collections import deque

def components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen, out = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r,c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r,c)])
            seen.add((r,c))
            cells = set()
            while q:
                y,x = q.popleft(); cells.add((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p); q.append(p)
            out.append((color,cells))
    return out

def variants(cells):
    forms=set()
    for reflect in (1,-1):
        for k in range(4):
            pts=[]
            for y,x in cells:
                x*=reflect
                for _ in range(k): y,x=x,-y
                pts.append((y,x))
            my=min(y for y,x in pts); mx=min(x for y,x in pts)
            forms.add(frozenset((y-my,x-mx) for y,x in pts))
    return forms

def subset_shape(small, large):
    if len(small) >= len(large): return False
    for form in variants(small):
        for ay,ax in large:
            if {(ay+y,ax+x) for y,x in form} <= large:
                return True
    return False

def transform(grid):
    h,w=len(grid),len(grid[0])
    freq={}
    for row in grid:
        for x in row: freq[x]=freq.get(x,0)+1
    bg=max(freq,key=freq.get)
    objs=components(grid,bg)
    candidates=[]
    for i,(col,cells) in enumerate(objs):
        for j,(hostcol,host) in enumerate(objs):
            if i==j or col==hostcol or len(cells)>=len(host): continue
            if subset_shape(cells,host):
                distance=min(abs(y-yy)+abs(x-xx) for y,x in cells for yy,xx in host)
                candidates.append((distance,-len(cells),-len(host),cells,hostcol))
    if not candidates: return [row[:] for row in grid]
    _,_,_,cells,newcolor=min(candidates,key=lambda z:z[:3])
    out=[row[:] for row in grid]
    for y,x in cells: out[y][x]=newcolor
    return out

