 h,w=len(g),len(g[0]); bg=Counter(x for row in g for x in row).most_common(1)[0][0]; seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   col=g[r][c]
   if col==bg or (r,c) in seen: continue
   seen.add((r,c)); q=deque([(r,c)]); s=set()
   while q:
    y,x=q.popleft(); s.add((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     yy,xx=y+dy,x+dx
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==col: seen.add((yy,xx)); q.append((yy,xx))
   out.append((col,s))
 return bg,out

def trans(g):
 bg,o=comps(g); z=[r[:] for r in g]; cand=[]
 for i,(col,s) in enumerate(o):
  r0=min(r for r,c in s); r1=max(r for r,c in s); c0=min(c for r,c in s); c1=max(c for r,c in s); h=r1-r0+1; w=c1-c0+1
  if h<3 or w<3 or len(s)/(h*w)>.65: continue
  for hr,vc in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
   if all((hr,c) in s for c in range(c0,c1+1)) and all((r,vc) in s for r in range(r0,r1+1)):
    ins=[(j,co,ss) for j,(co,ss) in enumerate(o) if j!=i and all(r0<=r<=r1 and c0<=c<=c1 for r,c in ss)]
    if ins:cand.append((len(s),i,col,(r0,r1,c0,c1),ins))
    break
 if not cand:return z
 _,fi,marker,(r0,r1,c0,c1),ins=max(cand,key=lambda x:(x[0],len(x[4])))
 # template group selected by which inside/outside components share exact silhouette
 def sig(s):
  a=min(r for r,c in s);b=min(c for r,c in s);return frozenset((r-a,c-b) for r,c in s)
 # Group all shapes represented both inside and outside, choose group with max total extent/area, then repaint outside members.
 groups={}
 for j,(co,s) in enumerate(o):
  if j==fi: continue
  inside=all(r0<=r<=r1 and c0<=c<=c1 for r,c in s)
  outside=any(not(r0<=r<=r1 and c0<=c<=c1) for r,c in s)
  groups.setdefault(sig(s),[]).append((j,co,s,inside,outside))
 valid=[]
 for sh,items in groups.items():
  a=[x for x in items if x[3]]; b=[x for x in items if x[4]]
  if a and b: valid.append((sum(len(x[2]) for x in items),sh,b))
 if valid:
  _,_,targets=max(valid,key=lambda x:x[0])
  for _,_,s,_,_ in targets:
   for r,c in s:z[r][c]=marker
 return z

