def transform(grid):
    h,w=len(grid),len(grid[0])
    # color 3 backdrop, 1 short bars, 8 clue
    out=[row[:] for row in grid]
    # local extension of clue-color row through interior to the right rail, while each bar's same-color columns extend fully
    for r in range(h):
        for c in range(w):
            if grid[r][c]==8:
                out[r][c]=4
                # extend rightward until edge or non-background
                cc=c+1
                while cc<w-1 and grid[r][cc]==3:
                    out[r][cc]=8; cc+=1
                # source clue region keeps left side unpainted unless in border-aligned bar lanes
    # opposing short 1-runs delimit columns whose interiors take the clue fill color
    for c in (1,2,3,5,6,7):
        for r in range(1,h-1):
            if grid[r][c]==3:out[r][c]=8
    # markers preserved as endpoint 4
    for r in range(h):
        for c in range(w):
            if grid[r][c]==8:out[r][c]=4
    return out
